+ */
+public class NoopStep extends ClusterStateWaitStep {
+    public static final String NAME = "noop";
+
+    public NoopStep(StepKey key, StepKey nextStepKey) {
+        super(key, nextStepKey);
+    }
+
+    @Override
+    public boolean isRetryable() {
